    "test": "node --experimental-strip-types server.ts > server.log 2>&1 & sleep 2 && node --experimental-strip-types client.ts > output.log 2>&1 ; cat output.log"
  },
  "dependencies": {
    "@trpc/server": "next",
    "@trpc/client": "next",
    "eventsource": "^2.0.2",
    "zod": "^3.22.4"
  }
}

